n = int(input())
words = input().split()
counts = {}
for w in words:
    w = w.lower()
    counts[w] = counts.get(w, 0) + 1
for word, count in sorted(counts.items(), key=lambda kv: (-kv[1], kv[0])):
    print(word, count)
